using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;

namespace OpenCodexLauncherV2
{
    public static class ModernTheme
    {
        public static readonly Brush Accent = new SolidColorBrush(Color.FromRgb(82,105,158));
        public static void Apply(Window window)
        {
            if (Application.Current != null && !Application.Current.Resources.Contains("ModernTheme"))
            {
                var dictionary = (ResourceDictionary)XamlReader.Parse(Resources);
                Application.Current.Resources.MergedDictionaries.Add(dictionary);
                Application.Current.Resources["ModernTheme"] = true;
            }
            window.FontFamily = new FontFamily("DengXian, Segoe UI");
            window.FontSize = 14; window.FontWeight = FontWeights.SemiBold; window.UseLayoutRounding = true; window.Background = Brushes.White;
        }
        public static void Primary(Button button) { button.Background=Accent; button.Foreground=Brushes.White; button.BorderBrush=Accent; }
