<Style TargetType='ComboBoxItem'><Setter Property='Padding' Value='10,8'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBoxItem'><Border x:Name='surface' CornerRadius='5' Padding='{TemplateBinding Padding}' Background='Transparent'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='surface' Property='Background' Value='#EDF1F8'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter Property='Foreground' Value='#52699E'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
